// regMemOp returns the operation of a load or store of memory 0 at an i32
// address, reporting whether op is one.
func regMemOp(op opcode.Opcode) (rop regOp, store, ok bool) {
	switch op {
	case opcode.I32LoadMem:
		return rI32LoadMem, false, true
	case opcode.I64LoadMem:
		return rI64LoadMem, false, true
	case opcode.F32LoadMem:
		return rF32LoadMem, false, true
	case opcode.F64LoadMem:
		return rF64LoadMem, false, true
	case opcode.I32LoadMem8S:
		return rI32LoadMem8S, false, true
	case opcode.I32LoadMem8U:
		return rI32LoadMem8U, false, true
	case opcode.I32LoadMem16S:
		return rI32LoadMem16S, false, true
	case opcode.I32LoadMem16U:
		return rI32LoadMem16U, false, true
	case opcode.I64LoadMem8S:
		return rI64LoadMem8S, false, true
	case opcode.I64LoadMem8U:
		return rI64LoadMem8U, false, true
	case opcode.I64LoadMem16S:
		return rI64LoadMem16S, false, true
	case opcode.I64LoadMem16U:
		return rI64LoadMem16U, false, true
	case opcode.I64LoadMem32S:
		return rI64LoadMem32S, false, true
	case opcode.I64LoadMem32U:
		return rI64LoadMem32U, false, true
	case opcode.I32StoreMem:
		return rI32StoreMem, true, true
	case opcode.I64StoreMem:
		return rI64StoreMem, true, true
	case opcode.F32StoreMem:
		return rF32StoreMem, true, true
	case opcode.F64StoreMem:
		return rF64StoreMem, true, true
	case opcode.I32StoreMem8:
		return rI32StoreMem8, true, true
	case opcode.I32StoreMem16:
		return rI32StoreMem16, true, true
	case opcode.I64StoreMem8:
		return rI64StoreMem8, true, true
	case opcode.I64StoreMem16:
		return rI64StoreMem16, true, true
	case opcode.I64StoreMem32:
		return rI64StoreMem32, true, true
	}
	return 0, false, false
}

